package lk.ac.sliit.ridelink.ride.infrastructure.persistence.adapter;
import lk.ac.sliit.ridelink.ride.domain.model.Ride; import lk.ac.sliit.ridelink.ride.domain.repository.RideRepository; import lk.ac.sliit.ridelink.ride.infrastructure.persistence.mapper.RidePersistenceMapper; import lk.ac.sliit.ridelink.ride.infrastructure.persistence.repository.SpringDataRideRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class RidePersistenceAdapter implements RideRepository {private final SpringDataRideRepository repository;public RidePersistenceAdapter(SpringDataRideRepository repository){this.repository=repository;}public Ride save(Ride r){return RidePersistenceMapper.domain(repository.saveAndFlush(RidePersistenceMapper.entity(r)));}public Optional<Ride> findById(UUID id){return repository.findById(id).map(RidePersistenceMapper::domain);}public List<Ride> findByPassengerId(UUID id){return repository.findByPassengerIdOrderByRequestedAtDesc(id).stream().map(RidePersistenceMapper::domain).toList();}public List<Ride> findByDriverId(UUID id){return repository.findByDriverIdOrderByRequestedAtDesc(id).stream().map(RidePersistenceMapper::domain).toList();}}
